import {validateMessage} from './validation.js';

// @spec-file specs/hal-engine-conversation-list/spec.md#39
it('preserves valid list pagination and rejects malformed limits and cursors', () => {
  const cursor = {sessionId: 's1', updatedAt: '2026-01-01T00:00:00.000Z'};
  const accepted = [
    {},
    {limit: 0},
    {limit: 201},
    {before: cursor},
    {limit: 10, before: {sessionId: 's'.repeat(128), updatedAt: 0}},
  ];
  for (const pagination of accepted) {
    expect(validateMessage({type: 'list_sessions', ...pagination, userId: 'someone-else'})).toEqual({
      valid: true,
      data: {type: 'list_sessions', ...pagination},
    });
  }
  const rejected = [
    ...[-1, 1.5, '10', null, Infinity, NaN].map(limit => ({limit})),
    ...[
      null,
      'cursor',
      [],
      {},
      {...cursor, sessionId: ''},
      {...cursor, sessionId: 's'.repeat(129)},
      {...cursor, sessionId: 1},
      {...cursor, updatedAt: 'not-a-date'},
      {...cursor, updatedAt: true},
      {...cursor, updatedAt: Infinity},
      {...cursor, updatedAt: 8640000000000001},
    ].map(before => ({before})),
  ];
  for (const pagination of rejected) {
    expect(validateMessage({type: 'list_sessions', ...pagination})).toEqual({
      valid: false,
      error: expect.stringContaining(Object.keys(pagination)[0]),
    });
  }
});
EOF
 timeout 300 npm test -- --runTestsByPath src/transport/ws/listSessionsPagination.test.ts --runInBand"

